#include <iostream>

int main() {
    const int capacity = 8;
    int values[capacity] = {10, 20, 30, 40};
    int length = 4;

    // 输入 2，输出 10 20 40。
    int index = 0;
    std::cin >> index;
    if (std::cin.fail()) {
        std::cout << "请输入一个整数下标。\n";
        return 1;
    }

    if (index < 0 || index >= length) {
        std::cout << "删除失败：下标超出范围。\n";
        return 1;
    }

    // 从左往右补上空位。
    for (int i = index; i < length - 1; ++i) {
        values[i] = values[i + 1];
    }
    --length;

    for (int i = 0; i < length; ++i) {
        if (i > 0) {
            std::cout << ' ';
        }
        std::cout << values[i];
    }
    std::cout << '\n';
    return 0;
}
